test_suite:
test('loading is true initially', () => {
  Object.assign(navigator, {
    geolocation: { getCurrentPosition: vi.fn() }
  });
  const { result } = renderHook(() => useGeolocation());
  expect(result.current.loading).toBe(true);
  expect(result.current.coords).toBeNull();
  expect(result.current.error).toBeNull();
});

test('sets coords on success', async () => {
  const mockCoords = { latitude: 51.5, longitude: -0.1 };
  Object.assign(navigator, {
    geolocation: {
      getCurrentPosition: vi.fn((success) => success({ coords: mockCoords }))
    }
  });
  const { result } = renderHook(() => useGeolocation());
  await act(async () => {});
  expect(result.current.loading).toBe(false);
  expect(result.current.coords).toEqual(mockCoords);
});

test('sets error on failure', async () => {
  const mockError = { code: 1, message: 'denied' };
  Object.assign(navigator, {
    geolocation: {
      getCurrentPosition: vi.fn((_, error) => error(mockError))
    }
  });
  const { result } = renderHook(() => useGeolocation());
  await act(async () => {});
  expect(result.current.loading).toBe(false);
  expect(result.current.error).toEqual(mockError);
});

// __hidden__
test('loading is false after response either way', async () => {
  Object.assign(navigator, {
    geolocation: {
      getCurrentPosition: vi.fn((success) => success({ coords: { latitude: 0, longitude: 0 } }))
    }
  });
  const { result } = renderHook(() => useGeolocation());
  await act(async () => {});
  expect(result.current.loading).toBe(false);
});

solution:
import { useEffect, useState } from 'react';

interface GeoState {
  coords: GeolocationCoordinates | null;
  loading: boolean;
  error: GeolocationPositionError | null;
}

export function useGeolocation(): GeoState {
  const [state, setState] = useState<GeoState>({
    coords: null,
    loading: true,
    error: null,
  });

  useEffect(() => {
    navigator.geolocation.getCurrentPosition(
      (position) => setState({ coords: position.coords, loading: false, error: null }),
      (error) => setState({ coords: null, loading: false, error })
    );
  }, []);

  return state;
}
